css:
.studio {
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  line-height: 1.4;
}
.studio main {
  margin: 0;
  padding: 0.5rem 1rem;
}
.studio .scrud-studio-links {
  display: flex;
  gap: 1rem;
  font-size: 0.875rem;
}
[data-studio-workbench] {
  display: grid;
  gap: 1rem;
}
.studio .studio-workbench {
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  gap: 0.5rem;
  min-height: 85vh;
}
.studio .studio-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  border-bottom: 1px solid #d0d0d0;
  padding-bottom: 0.25rem;
}
.studio .studio-title {
  font-size: 1.125rem;
  margin: 0;
}
.studio .studio-badge {
  font-size: 0.75rem;
  font-weight: normal;
  border: 1px solid #888;
  border-radius: 0.25rem;
  padding: 0 0.25rem;
}
.studio .studio-toggles {
  display: flex;
  gap: 0.25rem;
}
.studio .studio-toggle[aria-pressed="false"] {
  opacity: 0.6;
}
.studio .studio-notice {
  border: 1px solid #b00020;
  background: #fdecea;
  color: #5f0010;
  padding: 0.25rem 0.5rem;
}
.studio .studio-notice[hidden] {
  display: none;
}
.studio .studio-panes {
  display: flex;
  gap: 0.5rem;
  min-height: 0;
}
.studio .studio-pane {
  flex: 1 1 0;
  min-width: 0;
  overflow: auto;
  border: 1px solid #d0d0d0;
  border-radius: 0.25rem;
  padding: 0.5rem;
}
.studio .studio-pane[data-studio-pane="items"] {
  flex: 0 0 16rem;
}
.studio .studio-pane[data-studio-pane="preview"] {
  flex: 2 1 0;
}
.studio .studio-pane[data-studio-collapsed] {
  flex: 0 0 2rem;
  overflow: hidden;
  padding: 0.5rem 0.25rem;
}
.studio .studio-pane[data-studio-collapsed] > .studio-pane-body {
  display: none;
}
.studio .studio-pane[data-studio-collapsed] > .studio-pane-title {
  writing-mode: vertical-rl;
}
.studio .studio-pane-title {
  font-size: 0.875rem;
  margin: 0 0 0.5rem;
}
.studio .studio-preview {
  width: 100%;
  min-height: 60vh;
  border: 0;
  background: #fff;
}
.studio .studio-items ul {
  list-style: none;
  margin: 0;
  padding: 0;
}
.studio .studio-kind-title {
  font-size: 0.8125rem;
  margin: 0.5rem 0 0.25rem;
}
.studio .studio-item {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.25rem;
  padding: 0.125rem 0 0.125rem 0.25rem;
}
.studio .studio-open {
  background: none;
  border: 0;
  padding: 0;
  font: inherit;
  color: inherit;
  text-align: left;
  cursor: pointer;
}
.studio .studio-own .studio-open {
  font-weight: 600;
}
.studio .studio-packaged .studio-open {
  font-style: italic;
}
.studio .studio-origin,
.studio .studio-applies-to,
.studio .studio-conflict {
  font-size: 0.75rem;
  color: #555;
}
.studio .studio-conflict-parent,
.studio .studio-conflict-layer {
  border-left: 3px solid #b00020;
}
.studio .studio-conflict {
  color: #b00020;
}
.studio .studio-override {
  font-size: 0.75rem;
}
.studio .studio-strip {
  border-top: 1px solid #d0d0d0;
  padding-top: 0.25rem;
  font-size: 0.875rem;
}
.studio .studio-status {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
}
.studio .studio-chain {
  display: flex;
  gap: 0.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.studio .studio-chain-published {
  font-style: italic;
}
.studio .studio-count-conflicts {
  color: #b00020;
}
.studio .studio-actions {
  display: flex;
  gap: 0.5rem;
}
.studio .studio-pane[data-studio-collapsed] > .studio-editor-head,
.studio .studio-pane[data-studio-collapsed] > .studio-draft-errors {
  display: none;
}
.studio .studio-editor-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
}
.studio .studio-editor-head[hidden],
.studio .studio-draft-errors[hidden] {
  display: none;
}
.studio .studio-editor-title {
  font-size: 1rem;
  margin: 0;
}
.studio .studio-editor-origin,
.studio .studio-editor-meta {
  font-size: 0.75rem;
  color: #555;
}
.studio .studio-editor-meta {
  margin: 0 0 0.25rem;
}
.studio .studio-code {
  display: block;
  box-sizing: border-box;
  width: 100%;
  min-height: 20rem;
  margin: 0;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.8125rem;
  line-height: 1.45;
  tab-size: 2;
  white-space: pre;
  overflow: auto;
}
.studio .studio-code[readonly],
.studio pre.studio-code {
  background: #f6f6f6;
}
.studio .studio-code-label {
  display: block;
  font-size: 0.75rem;
  margin-bottom: 0.25rem;
}
.studio .studio-note {
  font-size: 0.8125rem;
  border-left: 3px solid #888;
  padding-left: 0.5rem;
}
.studio .studio-editor-actions,
.studio .studio-editor + .studio-revert {
  margin-top: 0.5rem;
}
.studio .studio-revert {
  font-size: 0.8125rem;
}
.studio .studio-draft-errors {
  margin-top: 0.5rem;
  border: 1px solid #b00020;
  padding: 0.25rem 0.5rem;
  font-size: 0.8125rem;
  color: #5f0010;
}
.studio .studio-draft-errors p,
.studio .studio-draft-errors ul {
  margin: 0;
}
